import{_ as a,o,c as t,a2 as s}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"MCP: Model Context Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"ia/mcp/01-introduccion-al-model-context-protocol.md","filePath":"ia/mcp/01-introduccion-al-model-context-protocol.md","lastUpdated":1789040978000,"isDraft":false}'),i={name:"ia/mcp/01-introduccion-al-model-context-protocol.md"};function n(r,e,l,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="mcp-model-context-protocol" tabindex="-1">MCP: Model Context Protocol <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP: Model Context Protocol&quot;">​</a></h1><p>El <strong>Model Context Protocol (MCP)</strong> es un estandar abierto para conectar aplicaciones de IA (clientes) con fuentes de datos y herramientas externas (servidores MCP). Define como exponer <strong>resources</strong>, <strong>prompts</strong> y <strong>tools</strong> de forma uniforme.</p><h2 id="capitulos" tabindex="-1">Capitulos <a class="header-anchor" href="#capitulos" aria-label="Permalink to &quot;Capitulos&quot;">​</a></h2><ol><li><a href="./01-introduccion-al-model-context-protocol">Introduccion al Model Context Protocol</a></li><li><a href="./02-clientes-servidores-y-herramientas">Clientes servidores y herramientas</a></li><li><a href="./03-recursos-prompts-y-tools">Recursos prompts y tools</a></li><li><a href="./04-autenticacion-y-seguridad">Autenticacion y seguridad</a></li><li><a href="./05-construccion-de-un-servidor-mcp">Construccion de un servidor MCP</a></li><li><a href="./06-integracion-con-agentes">Integracion con agentes</a></li><li><a href="./07-buenas-practicas">Buenas practicas</a></li></ol><h2 id="problema-que-resuelve" tabindex="-1">Problema que resuelve <a class="header-anchor" href="#problema-que-resuelve" aria-label="Permalink to &quot;Problema que resuelve&quot;">​</a></h2><p>Antes de MCP, cada IDE o agente integraba APIs propietarias:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cursor -&gt; integracion custom GitHub</span></span>
<span class="line"><span>Otro IDE -&gt; otra integracion GitHub</span></span>
<span class="line"><span>App propia -&gt; otra vez lo mismo</span></span></code></pre></div><p>MCP estandariza el contrato:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cliente MCP &lt;--- protocolo ---&gt; Servidor MCP (GitHub, DB, filesystem, ...)</span></span></code></pre></div><p>Un servidor MCP escrito una vez puede usarse desde varios clientes compatibles.</p><h2 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C[Cliente MCP\\nIDE / Agente] &lt;--&gt;|JSON-RPC| S[Servidor MCP]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S --&gt; T[Tools]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S --&gt; R[Resources]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S --&gt; P[Prompts]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; API[APIs / BD / FS]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R --&gt; API</span></span></code></pre></div><ul><li><strong>Cliente:</strong> Cursor, Claude Desktop, apps custom con SDK.</li><li><strong>Servidor:</strong> Proceso que implementa el protocolo y ejecuta acciones.</li><li><strong>Transporte:</strong> stdio (local), SSE/HTTP (remoto).</li></ul><h2 id="tres-primitivas" tabindex="-1">Tres primitivas <a class="header-anchor" href="#tres-primitivas" aria-label="Permalink to &quot;Tres primitivas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Primitiva</th><th>Que expone</th></tr></thead><tbody><tr><td><strong>Tools</strong></td><td>Acciones invocables (buscar, crear issue, query SQL)</td></tr><tr><td><strong>Resources</strong></td><td>Datos legibles (archivo, documento, esquema)</td></tr><tr><td><strong>Prompts</strong></td><td>Plantillas predefinidas para el usuario</td></tr></tbody></table><h2 id="ejemplo-mental" tabindex="-1">Ejemplo mental <a class="header-anchor" href="#ejemplo-mental" aria-label="Permalink to &quot;Ejemplo mental&quot;">​</a></h2><p>Servidor &quot;documentacion interna&quot;:</p><ul><li><strong>Tool:</strong> <code>search_docs(query)</code> — busca en indice.</li><li><strong>Resource:</strong> <code>manual://postgresql/backup</code> — contenido de un capitulo.</li><li><strong>Prompt:</strong> <code>review_api_design</code> — plantilla para revision de APIs.</li></ul><h2 id="casos-de-uso" tabindex="-1">Casos de uso <a class="header-anchor" href="#casos-de-uso" aria-label="Permalink to &quot;Casos de uso&quot;">​</a></h2><ul><li>IDE con acceso a repos, tickets, docs.</li><li>Agente con consultas a base de datos controladas.</li><li>RAG empresarial con fuentes vivas.</li><li>Automatizacion DevOps desde chat (con permisos estrictos).</li></ul><h2 id="mcp-vs-langchain-tools" tabindex="-1">MCP vs LangChain tools <a class="header-anchor" href="#mcp-vs-langchain-tools" aria-label="Permalink to &quot;MCP vs LangChain tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>MCP</th><th>LangChain tools</th></tr></thead><tbody><tr><td>Protocolo entre procesos/apps</td><td>Funciones dentro de tu app Python</td></tr><tr><td>Reutilizable entre clientes</td><td>Acoplado a tu codigo</td></tr><tr><td>Ideal integraciones IDE</td><td>Ideal logica de negocio interna</td></tr></tbody></table><p>Pueden coexistir: cliente MCP en IDE + LangChain en backend.</p><h2 id="relacion-con-otros-manuales" tabindex="-1">Relacion con otros manuales <a class="header-anchor" href="#relacion-con-otros-manuales" aria-label="Permalink to &quot;Relacion con otros manuales&quot;">​</a></h2><ul><li><a href="./../rag/01-introduccion-y-arquitectura">RAG</a> — recuperacion de conocimiento.</li><li><a href="./../langchain/01-introduccion">LangChain</a> — orquestacion de LLM y agents.</li></ul><h2 id="buenas-practicas-iniciales" tabindex="-1">Buenas practicas iniciales <a class="header-anchor" href="#buenas-practicas-iniciales" aria-label="Permalink to &quot;Buenas practicas iniciales&quot;">​</a></h2><ul><li>Empieza con un servidor pequeno (filesystem o docs).</li><li>Tools de solo lectura antes de escritura.</li><li>Logs de cada invocacion.</li><li>Versiona el servidor MCP como cualquier servicio.</li></ul><h2 id="errores-comunes" tabindex="-1">Errores comunes <a class="header-anchor" href="#errores-comunes" aria-label="Permalink to &quot;Errores comunes&quot;">​</a></h2><ul><li>Exponer demasiadas tools sin documentacion clara.</li><li>Servidor con permisos de admin del sistema.</li><li>Confundir MCP con el modelo LLM (MCP no es un modelo).</li><li>No validar argumentos en el servidor.</li><li>Transporte remoto sin TLS ni auth.</li></ul><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>El <a href="./02-clientes-servidores-y-herramientas">capitulo 2</a> detalla roles, transportes y ciclo de vida de una sesion MCP.</p>`,31)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
